internal static class Program {
 static string root=""; static int assertions; static readonly List<object> results=[];
 static void A(bool ok,string name){assertions++;if(!ok)throw new Exception(name); Console.WriteLine("ASSERT "+name);}
 static SqliteConnection Open(string path){var c=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=Path.Combine(path,"inventory.db"),Pooling=false}.ToString());c.Open();return c;}
 static void X(SqliteConnection c,string sql){using var q=c.CreateCommand();q.CommandText=sql;q.ExecuteNonQuery();}
 static long N(SqliteConnection c,string sql){using var q=c.CreateCommand();q.CommandText=sql;return Convert.ToInt64(q.ExecuteScalar());}
 static string F(SqliteConnection c,string table,string columns="*"){using var q=c.CreateCommand();q.CommandText="SELECT "+columns+" FROM "+table+" ORDER BY "+(table=="batch_entries"?"batch,entry_index":"id");using var r=q.ExecuteReader();var rows=new List<object[]>();while(r.Read()){var vals=new object[r.FieldCount];r.GetValues(vals);rows.Add(vals.Select(v=>v==DBNull.Value?null!:v).ToArray());}return Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(rows)));}
 static void Reject(Action a,string code){try{a();}catch(InvalidOperationException e)when(e.Message==code){A(true,"Reject "+code);return;}throw new Exception("Expected "+code);}
 static string Dir(string name){string p=Path.Combine(root,name);Directory.CreateDirectory(p);return p;}
