 static void Wait(InventoryEngine e,string task){for(int i=0;i<4000&&e.ReadTaskHeader(task).State=="Inventory";i++)Thread.Sleep(5);A(e.ReadTaskHeader(task).State!="Inventory","worker terminal");Thread.Sleep(25);}
 static void Legacy(int v,bool conflict=false){string s=State("legacy-"+v+(conflict?"-fail":""));string tid=Id();using(var p=new PrivateState(s))using(var c=Open(s)){
 X(c,"CREATE TABLE tasks(id TEXT PRIMARY KEY,owner TEXT NOT NULL,root TEXT NOT NULL,identity TEXT NOT NULL,state TEXT NOT NULL,created TEXT NOT NULL,updated TEXT NOT NULL,reason TEXT,revision INTEGER NOT NULL DEFAULT 1"+(v>=3?",scan_mode TEXT NULL CHECK(scan_mode IN ('Selected','AllFixedDisks'))":"")+");CREATE TABLE objects(id INTEGER PRIMARY KEY AUTOINCREMENT,task TEXT NOT NULL,path TEXT NOT NULL,parent INTEGER,kind TEXT NOT NULL,identity TEXT,attributes INTEGER,links INTEGER,logical INTEGER,allocated INTEGER,modified TEXT,observed TEXT NOT NULL,coverage TEXT NOT NULL,reason TEXT,scan TEXT NOT NULL,protection TEXT NOT NULL"+(v>=2?",enumeration_complete INTEGER NULL":"")+");CREATE INDEX pending ON objects(task,scan,id);CREATE INDEX children ON objects(task,parent,id);CREATE INDEX largefiles ON objects(task,kind,logical DESC,id);PRAGMA user_version="+v);
 using var q=c.CreateCommand();q.CommandText="INSERT INTO tasks(id,owner,root,identity,state,created,updated,reason,revision) VALUES($id,$owner,'E:\\synthetic','identity-old','Ready','old-created','old-updated','legacy-reason',7);INSERT INTO objects(task,path,kind,logical,observed,coverage,scan,protection) VALUES($id,'E:\\synthetic','Directory',123,'old-observed','Complete','Done','ReadOnly')";q.Parameters.AddWithValue("$id",tid);q.Parameters.AddWithValue("$owner",p.OwnerSid);q.ExecuteNonQuery();if(conflict)X(c,"CREATE TABLE batches(collision INTEGER)");}
 string tf,of;const string tc="id,owner,root,identity,state,created,updated,reason,revision",oc="id,task,path,parent,kind,identity,attributes,links,logical,allocated,modified,observed,coverage,reason,scan,protection";using(var c=Open(s)){tf=F(c,"tasks",tc);of=F(c,"objects",oc);}
 if(conflict){bool failed=false;try{using var e=new InventoryEngine(s);}catch(SqliteException){failed=true;}A(failed,"migration collision raises");using(var p=new PrivateState(s))A(true,"migration failure releases lock");using var c=Open(s);A(N(c,"PRAGMA user_version")==v,"migration schema rollback");A(F(c,"tasks",tc)==tf&&F(c,"objects",oc)==of,"migration failure old facts unchanged");A(N(c,"SELECT count(*) FROM pragma_table_info('tasks') WHERE name='scan_mode'")==0,"migration ALTER rolled back");return;}
 using(var e=new InventoryEngine(s)){using var c=Open(s);A(N(c,"PRAGMA user_version")==4,"v"+v+" upgraded4");A(F(c,"tasks",tc)==tf&&F(c,"objects",oc)==of,"v"+v+" exact legacy facts unchanged");A(N(c,"SELECT count(*) FROM tasks WHERE scan_mode IS NULL")==1&&N(c,"SELECT count(*) FROM objects WHERE enumeration_complete IS NULL")==1,"legacy no fabricated proof/mode");A(e.ListBatches(null,64).Items.Count==0,"legacy no fabricated batches");}}
 static void Unknown(){string s=State("unknown");using(var p=new PrivateState(s))using(var c=Open(s))X(c,"PRAGMA user_version=99");Reject(()=>{using var e=new InventoryEngine(s);},"UnknownDatabaseSchema");using(var p=new PrivateState(s))A(true,"unknown releases private lock");using var db=Open(s);A(N(db,"PRAGMA user_version")==99,"unknown version not rewritten");}
 static void Pages(){string s=State("pages"),tree=Dir("page-tree");var ids=new HashSet<string>();using(var e=new InventoryEngine(s)){for(int i=0;i<65;i++){var b=e.CreateBatch(Id(),[tree]);ids.Add(b.BatchId);e.StopBatch(b.BatchId,b.Revision);}var p=e.ListBatches(null,64);var p2=e.ListBatches(p.NextAfterBatchId,64);A(p.Items.Count==64&&p2.Items.Count==1&&p2.NextAfterBatchId==null,"65 pages 64+1 termination");A(p.Items.Concat(p2.Items).Select(b=>b.BatchId).ToHashSet().SetEquals(ids),"65 no duplicate or loss");}using(var e=new InventoryEngine(s)){var p=e.ListBatches(null,64);var p2=e.ListBatches(p.NextAfterBatchId,64);A(p.Items.Concat(p2.Items).Select(b=>b.BatchId).ToHashSet().SetEquals(ids),"65 reopen stable IDs");A(p.Items.Concat(p2.Items).All(b=>b.State=="Stopped"&&e.GetBatch(b.BatchId).Entries.Single().TaskId==null),"reopen no task/autoscan");}}
 static void Transaction(){string s=State("transaction"),tree=Dir("transaction-tree");File.WriteAllText(Path.Combine(tree,"source.tmp"),"artificial");using var e=new InventoryEngine(s);var b=e.CreateBatch(Id(),[tree]);using(var c=Open(s)){string[] tables=["tasks","objects","batches","batch_entries"];var before=tables.Select(t=>F(c,t)).ToArray();X(c,"CREATE TRIGGER fail_start BEFORE UPDATE OF task ON batch_entries WHEN NEW.task IS NOT NULL BEGIN SELECT RAISE(ABORT,'artificial-start-fault'); END");bool rejected=false;try{e.StartBatchEntry(b.BatchId,0,b.Revision);}catch(SqliteException ex){rejected=ex.Message.Contains("artificial-start-fault");}A(rejected,"Start injected failure raised");A(tables.Select(t=>F(c,t)).SequenceEqual(before),"Start rollback all four tables conserved no orphan");A(N(c,"SELECT COUNT(*) FROM tasks")==0&&N(c,"SELECT COUNT(*) FROM objects")==0,"Start no orphan task/object");X(c,"DROP TRIGGER fail_start");}
 e.StartBatchEntry(b.BatchId,0,b.Revision);var query=e.GetBatch(b.BatchId);string task=query.Entries.Single().TaskId!;A(task!=null,"lost response recovered binding by query");Wait(e,task!);Reject(()=>e.StartBatchEntry(b.BatchId,0,b.Revision),"BatchRevisionChanged");using(var c=Open(s))A(N(c,"SELECT count(*) FROM tasks")==1,"lost response duplicate creates no task");}
 static void LowQuotaControl(){string s=State("quota-control"),tree=Dir("quota-tree");using var e=new InventoryEngine(s,new ExplorerLimits(MaxStateBytes:2097152));var b=e.CreateBatch(Id(),[tree]);using(var c=Open(s))X(c,"CREATE TABLE artificial_padding(v BLOB);INSERT INTO artificial_padding VALUES(zeroblob(1600000));PRAGMA wal_checkpoint(TRUNCATE)");A(e.GetStorageInfo().TotalBytes>1572864,"fixture leaves less512KiB metadata reserve");e.CancelBatch(b.BatchId,b.Revision);A(e.GetBatch(b.BatchId).State=="Cancelled","low quota cancellation remains usable");}
 static void AllFailed(){string s=State("all-failed"),missing=Path.Combine(root,"never-created-missing-root");using var e=new InventoryEngine(s);var b=e.CreateBatch(Id(),[missing]);A(b.Entries.Single().State=="Failed","unavailable root recorded Failed");A(b.State!="Running","all failed batch is terminal not Running");var next=e.CreateBatch(Id(),[Dir("after-failed-tree")]);A(next.BatchId!=b.BatchId,"all failed releases active slot");}
 static void Backup(){string s=State("backup-state"),tree=Dir("backup-tree");File.WriteAllText(Path.Combine(tree,"fact.txt"),"preserve");using var e=new InventoryEngine(s);var b=e.CreateBatch(Id(),[tree]);var start=e.StartBatchEntry(b.BatchId,0,b.Revision);Wait(e,start.TaskId!);string[] tables=["tasks","objects","batches","batch_entries"];string[] before;using(var c=Open(s))before=tables.Select(t=>F(c,t)).ToArray();var compact=e.CompactState(true);using(var c=Open(s))A(tables.Select(t=>F(c,t)).SequenceEqual(before),"compaction source full four-table fingerprint unchanged");string restore=State("independent-restore");using(var p=new PrivateState(restore))File.Copy(compact.BackupPath,Path.Combine(restore,"inventory.db"),false);using(var r=new InventoryEngine(restore)){using var c=Open(restore);A(tables.Select(t=>F(c,t)).SequenceEqual(before),"independent restore full four-table fingerprint unchanged");A(r.GetBatch(b.BatchId).Entries.Single().TaskId==start.TaskId,"restore binding preserved");}using var manifest=JsonDocument.Parse(File.ReadAllText(Path.Combine(Path.GetDirectoryName(compact.BackupPath)!,"manifest.json")));var m=manifest.RootElement;A(m.GetProperty("SchemaVersion").GetInt32()==4&&m.GetProperty("Tasks").GetInt32()==1&&m.GetProperty("Batches").GetInt32()==1&&m.GetProperty("BatchEntries").GetInt32()==1&&m.GetProperty("Objects").GetInt32()==2,"manifest schema4 all four counts");}
 public static int Main(string[] args){if(args.Length!=1)throw new ArgumentException("Explicit retained evidence parent required");root=TestEvidence.CreateFixture(args[0],"batch-fixture");Directory.CreateDirectory(root);Case("SQLiteSmoke",()=>{using var e=new InventoryEngine(State("smoke-state"));using var c=Open(State("smoke-state"));A(N(c,"PRAGMA user_version")==4,"real SQLite schema4");});Case("Migration-v1",()=>Legacy(1));Case("Migration-v2",()=>Legacy(2));Case("Migration-v3",()=>Legacy(3));Case("MigrationFailureLockRollback",()=>Legacy(1,true));Case("UnknownSchemaLock",Unknown);Case("65BatchesPaginationReopen",Pages);Case("StartTransactionRollbackAndLostResponse",Transaction);Case("LowQuotaCancellation",LowQuotaControl);Case("AllRootsFailed",AllFailed);Case("BackupFourTablesRestore",Backup);Case("ActiveWorkerLifecycle",()=>BatchLifecycle.Run(root,A));return results.Any(x=>JsonSerializer.SerializeToElement(x).GetProperty("status").GetString()=="Failed")?1:0;}
